/// 強連結成分分解（SCC）
///
/// 戻り値:
/// - comp[v] = 頂点 v が属する強連結成分の番号
///
/// 成分番号はトポロジカル順
/// 異なる成分間に u -> v の辺がある場合 comp[u] <= comp[v]
#[inline(always)]
pub fn scc(graph: &[Vec<usize>]) -> Vec<usize> {
    let n = graph.len();

    // 逆向きグラフを作る
    let mut rev = vec![vec![]; n];

    for v in 0..n {
        for &to in &graph[v] {
            rev[to].push(v);
        }
    }

    // 1回目のDFS
    // 帰りがけ順を求める
    let mut used = vec![false; n];
    let mut order = Vec::with_capacity(n);

    for start in 0..n {
        continueif!(used[start]);

        // 再帰を避けるためスタックでDFS (頂点, 次に見る辺の位置)
        let mut stack = vec![(start, 0)];
        used[start] = true;

        while let Some((v, i)) = stack.pop() {
            if i < graph[v].len() {
                // 続きから探索したいので積み直し
                stack.push((v, i + 1));

                let to = graph[v][i];

                if !used[to] {
                    used[to] = true;
                    stack.push((to, 0));
                }
            } else {
                // 全ての子を探索した
                order.push(v);
            }
        }
    }

    // 2回目のDFS
    // 逆グラフをorderの逆順に
    let mut comp = vec![usize::MAX; n];
    let mut group_id = 0;

    for &start in order.iter().rev() {
        continueif!(comp[start] != usize::MAX);

        let mut stack = vec![start];
        comp[start] = group_id;

        while let Some(v) = stack.pop() {
            for &to in &rev[v] {
                if comp[to] == usize::MAX {
                    comp[to] = group_id;
                    stack.push(to);
                }
            }
        }

        group_id += 1;
    }

    return comp;
}
